html:
{%- set datos = frappe.call("tz_gobierno.activos.datos_etiqueta", asset=doc.name) -%}
<div class="etiqueta-activo">
	<div class="etiqueta-qr">{{ datos.qr }}</div>
	<div class="etiqueta-texto">
		<div class="etiqueta-institucion">{{ doc.company }}</div>
		<div class="etiqueta-nombre">{{ doc.asset_name }}</div>
		<div class="etiqueta-codigo">
			B.N. {{ datos.codigo_bienes_nacionales or "—" }}
		</div>
		<div class="etiqueta-id">{{ doc.name }}</div>
	</div>
</div>

<style>
	/* 5cm x 3cm: el tamaño de etiqueta que pide el pliego. */
	.etiqueta-activo {
		width: 5cm;
		height: 3cm;
		display: flex;
		align-items: center;
		gap: 2mm;
		padding: 2mm;
		box-sizing: border-box;
		border: 0.3mm solid #000;
		font-family: Helvetica, Arial, sans-serif;
		overflow: hidden;
	}
	.etiqueta-qr { flex: 0 0 auto; line-height: 0; }
	.etiqueta-qr svg { width: 20mm; height: 20mm; }
	.etiqueta-texto { flex: 1 1 auto; min-width: 0; }
	.etiqueta-institucion {
		font-size: 5pt; text-transform: uppercase; letter-spacing: 0.2pt;
		white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
	}
	.etiqueta-nombre {
		font-size: 7pt; font-weight: bold; line-height: 1.15;
		max-height: 2.4em; overflow: hidden;
	}
	.etiqueta-codigo { font-size: 8pt; font-weight: bold; margin-top: 0.5mm; }
	.etiqueta-id { font-size: 5pt; color: #444; }
	@media print { .etiqueta-activo { border: 0.3mm solid #000; } }
</style>
